import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{C as i,S as a,_ as o,a as s,b as c,c as l,d as u,f as d,g as f,h as p,l as m,m as h,o as g,p as _,s as v,u as y,v as b,w as x,x as S,y as C}from"./chunks/assets.8isJ-IUK.js";var w=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}`),T={name:`troubleshooting.md`},E=x+` 1x, `+i+` 2x`,D=a+` 1x, `+S+` 2x`,O=c+` 1x, `+C+` 2x`,k=b+` 1x, `+o+` 2x`,A=f+` 1x, `+p+` 2x`,j=h+` 1x, `+_+` 2x`,M=d+` 1x, `+u+` 2x`,N=y+` 1x, `+m+` 2x`,P=l+` 1x, `+v+` 2x`,F=g+` 1x, `+s+` 2x`;function I(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><p>The module has a a troubleshooting page to fix common problems.<br> To access this page, open the main configuration page of the module then click the <strong>Troubleshooting</strong> button</p><p><img src="/webp/troubleshooting.jpg-90-1788222277578.webp" srcset="`+E+`" alt="Troubleshooting" title="" width="1482" height="840" loading="lazy" style="width:741px;"></p><h2 id="the-module-is-not-displayed" tabindex="-1">The module is not displayed <a class="header-anchor" href="#the-module-is-not-displayed" aria-label="Permalink to “The module is not displayed”">​</a></h2><p>Sometimes, the module gets removed from a necessary hook such as the hook which displays the fields in the product page.<br> This usually occurs after installing or activating a new theme.</p><p>To fix this, you can restore the module hooks like this:</p><p><img src="/webp/hooks-list.jpg-90-1788222277559.webp" srcset="`+D+`" alt="Hooks list" title="" width="1520" height="664" loading="lazy" style="width:760px;"></p><p>The module will then restore the hooks and show this confirmation</p><p><img src="/webp/hooks-restored.jpg-90-1788222277559.webp" srcset="`+O+`" alt="Hooks restored" title="" width="1520" height="816" loading="lazy" style="width:760px;"></p><p>You can also restore the module hooks in the <code>Design</code> &gt; <code>Positions</code> page.</p><h2 id="the-customization-is-not-formatted-correctly" tabindex="-1">The customization is not formatted correctly <a class="header-anchor" href="#the-customization-is-not-formatted-correctly" aria-label="Permalink to “The customization is not formatted correctly”">​</a></h2><p>By default, PrestaShop does not display a customization that contains HTML content, so instead of the customization summary, the HTML code will be displayed.</p><p><img src="/webp/customization-html.jpg-90-1788222277546.webp" srcset="`+k+`" alt="Customization HTML" title="" width="1410" height="774" loading="lazy" style="width:705px;"></p><p>To fix this, apply the template fixes in the troubleshooting page</p><p><img src="/webp/template-fix.jpg-90-1788222277577.webp" srcset="`+A+`" alt="Template fix" title="" width="1520" height="694" loading="lazy" style="width:760px;"></p><p>The module will display this confirmation if the fix was applied successfully</p><p><img src="/webp/template-fix-applied.jpg-90-1788222277576.webp" srcset="`+j+`" alt="Template fix applied" title="" width="1520" height="744" loading="lazy" style="width:760px;"></p><div class="tip custom-block"><p class="custom-block-title">Clear the PrestaShop cache after applying the template fix</p></div><p>The customization will be displayed like this</p><p><img src="/webp/customization-formatted.jpg-90-1788222277544.webp" srcset="`+M+`" alt="Customization formatted" title="" width="1410" height="770" loading="lazy" style="width:705px;"></p><p>If this doesn&#39;t work, it means that either that the module couldn&#39;t fix the files because of a permission problem on your server or that PrestaShop could not clear the cache properly due to insufficient permissions.</p><p>In that case, you need to perform the edits manually by following <a href="https://gist.github.com/unlocomqx/f0b86a1ce938405c315d5de979011b95" target="_blank" rel="noreferrer">this guide</a></p><p>After applying the fix, make sure to also delete or rename the folder <code>/var/cache</code> manually if needed.</p><h2 id="upgrade-checker" tabindex="-1">Upgrade checker <a class="header-anchor" href="#upgrade-checker" aria-label="Permalink to “Upgrade checker”">​</a></h2><p>You can check the module installation using the upgrade checker</p><p>To access it, click this button which you can find in the module configuration page</p><p><img src="/webp/upgrade-checker-btn.png-90-1788222277580.webp" srcset="`+N+`" alt="Upgrade checker" title="" width="1144" height="528" loading="lazy" style="width:572px;"></p><p>The versions will be displayed like this</p><p><img src="/webp/versions-list.jpg-90-1788222277580.webp" srcset="`+P+`" alt="Version list" title="" width="1234" height="874" loading="lazy" style="width:617px;"></p><p>If an upgrade has previously failed, you can retry it like this</p><p><img src="/webp/retry-upgrade.png-90-1788222277573.webp" srcset="`+F+`" alt="Retry upgrade" title="" width="660" height="894" loading="lazy" style="width:330px;"></p>`,31)]])}var L=e(T,[[`render`,I]]);export{w as __pageData,L as default};